package dynamo

import (
	"context"
	"errors"
	"fmt"
	"math"
	"slices"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/feature/dynamodb/attributevalue"
	"github.com/aws/aws-sdk-go-v2/feature/dynamodb/expression"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb/types"

	kbdbctx "github.com/rogueserenity/kbdb/internal/ctx"
	"github.com/rogueserenity/kbdb/internal/log"
	"github.com/rogueserenity/kbdb/internal/repository"
)

// ImageID is meant to be server-generated by the handler before reaching
// this layer; an empty value means a caller skipped that step.
var errEmptyImageID = errors.New("image id must not be empty")

var errDuplicateImageID = errors.New("image id already exists in this build")

// Should be unreachable in practice.
var errImageMissingAfterAdd = errors.New("image not found in build after AddImage")

// DeleteImage treats this as success, not an error.
var errImageAlreadyAbsent = errors.New("image already absent from build")

// BuildRepository is the DynamoDB-backed repository.BuildRepository.
type BuildRepository struct {
	client    dynamoAPI
	tableName string
}

var _ repository.BuildRepository = (*BuildRepository)(nil)

// NewBuildRepository returns a BuildRepository backed by client.
func NewBuildRepository(client *dynamodb.Client, tableName string) *BuildRepository {
	return &BuildRepository{client: client, tableName: tableName}
}

// List implements repository.BuildRepository.
func (r *BuildRepository) List(
	ctx context.Context,
	ownerID string,
	visibilities []repository.Visibility,
	limit int,
	cursor string,
) ([]repository.Build, string, error) {
	// No visibility tier is readable, so nothing can match - short-circuit
	// rather than build a Query with an empty IN(...) filter (which the
	// expression builder below would panic constructing).
	if len(visibilities) == 0 {
		return []repository.Build{}, "", nil
	}

	startKey, err := decodeCursor(cursor)
	if err != nil {
		return nil, "", fmt.Errorf("decoding cursor: %w", err)
	}

	// limit is validated by the handler against api/openapi.yaml's Limit
	// parameter (1-100) before reaching here; List's exported signature
	// accepts any int, so clamp defensively rather than trust that.
	if limit < 1 {
		limit = 1
	} else if limit > math.MaxInt32 {
		limit = math.MaxInt32
	}

	visValues := make([]expression.OperandBuilder, len(visibilities))
	for i, v := range visibilities {
		visValues[i] = expression.Value(v)
	}

	builder := expression.NewBuilder().
		WithKeyCondition(expression.Key("user_id").Equal(expression.Value(ownerID))).
		WithFilter(expression.Name("visibility").In(visValues[0], visValues[1:]...))

	expr, err := builder.Build()
	if err != nil {
		return nil, "", fmt.Errorf("building build list expression: %w", err)
	}

	out, err := r.client.Query(ctx, &dynamodb.QueryInput{
		TableName:                 &r.tableName,
		KeyConditionExpression:    expr.KeyCondition(),
		FilterExpression:          expr.Filter(),
		ExpressionAttributeNames:  expr.Names(),
		ExpressionAttributeValues: expr.Values(),
		ExclusiveStartKey:         startKey,
		Limit:                     aws.Int32(int32(limit)),
	})
	if err != nil {
		return nil, "", fmt.Errorf("querying builds for owner %q: %w", ownerID, err)
	}

	builds := []repository.Build{}
	if err := attributevalue.UnmarshalListOfMaps(out.Items, &builds); err != nil {
		return nil, "", fmt.Errorf("unmarshalling builds for owner %q: %w", ownerID, err)
	}

	nextCursor, err := encodeCursor(out.LastEvaluatedKey)
	if err != nil {
		return nil, "", fmt.Errorf("encoding next cursor: %w", err)
	}

	return builds, nextCursor, nil
}

// Get implements repository.BuildRepository.
func (r *BuildRepository) Get(ctx context.Context, ownerID, id string) (*repository.Build, error) {
	out, err := r.client.GetItem(ctx, &dynamodb.GetItemInput{
		TableName: &r.tableName,
		Key: map[string]types.AttributeValue{
			"user_id": &types.AttributeValueMemberS{Value: ownerID},
			"id":      &types.AttributeValueMemberS{Value: id},
		},
	})
	if err != nil {
		return nil, fmt.Errorf("getting build %q for owner %q: %w", id, ownerID, err)
	}

	if len(out.Item) == 0 {
		return nil, repository.ErrNotFound
	}

	var b repository.Build
	if err := attributevalue.UnmarshalMap(out.Item, &b); err != nil {
		return nil, fmt.Errorf("unmarshalling build %q for owner %q: %w", id, ownerID, err)
	}

	return &b, nil
}

// Create implements repository.BuildRepository.
func (r *BuildRepository) Create(ctx context.Context, b repository.Build) (*repository.Build, error) {
	ownerID, ok := kbdbctx.UserID(ctx)
	if !ok {
		return nil, fmt.Errorf("creating build %q: %w", b.ID, repository.ErrNoUserID)
	}
	b.UserID = ownerID

	item, err := attributevalue.MarshalMap(b)
	if err != nil {
		return nil, fmt.Errorf("marshalling build %q for owner %q: %w", b.ID, b.UserID, err)
	}

	_, err = r.client.PutItem(ctx, &dynamodb.PutItemInput{
		TableName:           &r.tableName,
		Item:                item,
		ConditionExpression: aws.String("attribute_not_exists(id)"),
	})
	if err != nil {
		var condErr *types.ConditionalCheckFailedException
		if errors.As(err, &condErr) {
			return nil, repository.ErrAlreadyExists
		}
		return nil, fmt.Errorf("creating build %q for owner %q: %w", b.ID, b.UserID, err)
	}

	return &b, nil
}

// Update goes through mutateBuild rather than a naive whole-item PutItem:
// b (built from the request body) never has Images or Version set, so
// overwriting the stored item wholesale would wipe every image and desync
// Version from mutateBuild's CAS loop.
func (r *BuildRepository) Update(ctx context.Context, b repository.Build) (*repository.Build, error) {
	ownerID, ok := kbdbctx.UserID(ctx)
	if !ok {
		return nil, fmt.Errorf("updating build %q: %w", b.ID, repository.ErrNoUserID)
	}

	updated, err := r.mutateBuild(ctx, ownerID, b.ID, func(existing *repository.Build) error {
		existing.Keyboard = b.Keyboard
		existing.Plate = b.Plate
		existing.CaseMountType = b.CaseMountType
		existing.Stabs = b.Stabs
		existing.Foam = b.Foam
		existing.Switches = b.Switches
		existing.KeycapKits = b.KeycapKits
		existing.BuildDate = b.BuildDate
		existing.Notes = b.Notes
		existing.Visibility = b.Visibility
		return nil
	})
	if errors.Is(err, repository.ErrNotFound) {
		return nil, repository.ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("updating build %q for owner %q: %w", b.ID, ownerID, err)
	}

	return updated, nil
}

// Delete implements repository.BuildRepository.
func (r *BuildRepository) Delete(ctx context.Context, id string) ([]repository.BuildImageKey, error) {
	ownerID, ok := kbdbctx.UserID(ctx)
	if !ok {
		return nil, fmt.Errorf("deleting build %q: %w", id, repository.ErrNoUserID)
	}

	out, err := r.client.DeleteItem(ctx, &dynamodb.DeleteItemInput{
		TableName: &r.tableName,
		Key: map[string]types.AttributeValue{
			"user_id": &types.AttributeValueMemberS{Value: ownerID},
			"id":      &types.AttributeValueMemberS{Value: id},
		},
		ReturnValues: types.ReturnValueAllOld,
	})
	if err != nil {
		return nil, fmt.Errorf("deleting build %q for owner %q: %w", id, ownerID, err)
	}

	if len(out.Attributes) == 0 {
		return nil, repository.ErrNotFound
	}

	var deleted repository.Build
	if err := attributevalue.UnmarshalMap(out.Attributes, &deleted); err != nil {
		return nil, fmt.Errorf("unmarshalling deleted build %q for owner %q: %w", id, ownerID, err)
	}

	imageKeys := make([]repository.BuildImageKey, len(deleted.Images))
	for i, image := range deleted.Images {
		imageKeys[i] = image.Path
	}

	return imageKeys, nil
}

const maxBuildMutationAttempts = 3

// mutateBuild is a hand-rolled Version-based CAS retry loop: DynamoDB can't
// address a List element by an inner field like image_id, so image
// mutations must decode/mutate/re-encode the whole Images slice, and the Go
// SDK has no built-in optimistic-locking primitive. Mirrors keycap_set.go's
// mutateSet.
func (r *BuildRepository) mutateBuild(
	ctx context.Context,
	ownerID, buildID string,
	mutate func(b *repository.Build) error,
) (*repository.Build, error) {
	for range maxBuildMutationAttempts {
		b, err := r.Get(ctx, ownerID, buildID)
		if err != nil {
			return nil, err
		}

		if err := mutate(b); err != nil {
			return nil, err
		}

		expectedVersion := b.Version
		b.Version++

		item, err := attributevalue.MarshalMap(*b)
		if err != nil {
			return nil, fmt.Errorf("marshalling build %q for owner %q: %w", buildID, ownerID, err)
		}

		expr, err := expression.NewBuilder().
			WithCondition(expression.Name("version").Equal(expression.Value(expectedVersion))).
			Build()
		if err != nil {
			return nil, fmt.Errorf("building build mutation condition for build %q: %w", buildID, err)
		}

		_, err = r.client.PutItem(ctx, &dynamodb.PutItemInput{
			TableName:                 &r.tableName,
			Item:                      item,
			ConditionExpression:       expr.Condition(),
			ExpressionAttributeNames:  expr.Names(),
			ExpressionAttributeValues: expr.Values(),
		})
		if err == nil {
			return b, nil
		}

		var condErr *types.ConditionalCheckFailedException
		if !errors.As(err, &condErr) {
			return nil, fmt.Errorf("mutating build %q owner %q: %w", buildID, ownerID, err)
		}
		// Lost the CAS race - another writer updated Version first. Loop
		// and retry from a fresh Get.
		log.FromContext(ctx).Warn("build CAS retry", log.BuildID, buildID, "attempted_version", expectedVersion)
	}

	return nil, fmt.Errorf("mutating build %q owner %q: %w", buildID, ownerID, repository.ErrMutationConflict)
}

// AddImage implements repository.BuildRepository.
func (r *BuildRepository) AddImage(ctx context.Context, buildID string, image repository.BuildImage) (*repository.BuildImage, error) {
	if image.ImageID == "" {
		return nil, fmt.Errorf("adding image to build %q: %w", buildID, errEmptyImageID)
	}

	ownerID, ok := kbdbctx.UserID(ctx)
	if !ok {
		return nil, fmt.Errorf("adding image to build %q: %w", buildID, repository.ErrNoUserID)
	}

	updated, err := r.mutateBuild(ctx, ownerID, buildID, func(b *repository.Build) error {
		if slices.ContainsFunc(b.Images, func(existing repository.BuildImage) bool { return existing.ImageID == image.ImageID }) {
			return fmt.Errorf("adding image %q to build %q: %w", image.ImageID, buildID, errDuplicateImageID)
		}
		b.Images = append(b.Images, image)
		return nil
	})
	if err != nil {
		return nil, err
	}

	idx := slices.IndexFunc(updated.Images, func(i repository.BuildImage) bool { return i.ImageID == image.ImageID })
	if idx == -1 {
		return nil, fmt.Errorf("adding image %q to build %q: %w", image.ImageID, buildID, errImageMissingAfterAdd)
	}

	return &updated.Images[idx], nil
}

// DeleteImage implements repository.BuildRepository.
func (r *BuildRepository) DeleteImage(ctx context.Context, buildID, imageID string) (*repository.BuildImageKey, error) {
	ownerID, ok := kbdbctx.UserID(ctx)
	if !ok {
		return nil, fmt.Errorf("deleting image from build %q: %w", buildID, repository.ErrNoUserID)
	}

	var removed *repository.BuildImageKey
	_, err := r.mutateBuild(ctx, ownerID, buildID, func(b *repository.Build) error {
		idx := slices.IndexFunc(b.Images, func(existing repository.BuildImage) bool { return existing.ImageID == imageID })
		if idx == -1 {
			return errImageAlreadyAbsent
		}
		key := b.Images[idx].Path
		removed = &key
		b.Images = slices.Delete(b.Images, idx, idx+1)
		return nil
	})
	if errors.Is(err, errImageAlreadyAbsent) {
		return nil, nil //nolint:nilnil // no such image already absent is a valid, expected result
	}
	if err != nil {
		return nil, err
	}

	return removed, nil
}
